CREATE OR REPLACE FUNCTION public.delete_my_account_content(p_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
DELETE FROM public.side_income_reports WHERE user_id=p_user_id;
DELETE FROM public.activity_submissions WHERE user_id=p_user_id;
DELETE FROM public.lesson_progress WHERE user_id=p_user_id;
DELETE FROM public.quiz_results WHERE user_id=p_user_id;
DELETE FROM public.user_progress WHERE user_id=p_user_id;
DELETE FROM public.result_feedback WHERE user_id=p_user_id;
DELETE FROM public.assessment_results WHERE user_id=p_user_id;
DELETE FROM public.course_enrollments WHERE user_id=p_user_id;
DELETE FROM public.side_income_assessments WHERE user_id=p_user_id;
DELETE FROM public.create_it_blueprints WHERE user_id=p_user_id;
DELETE FROM public.conversation_context WHERE user_id=p_user_id;
DELETE FROM public.user_preferences WHERE user_id=p_user_id;
DELETE FROM public.subscribers_public WHERE user_id=p_user_id;
DELETE FROM public.subscribers_secure WHERE user_id=p_user_id;
DELETE FROM public.credit_reservations WHERE user_id=p_user_id;
DELETE FROM public.profiles WHERE id=p_user_id;
DELETE FROM public.users WHERE id=p_user_id;
END $$;
REVOKE ALL ON FUNCTION public.delete_my_account_content(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.delete_my_account_content(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.check_and_increment_ai_usage(p_user_id uuid,p_tool_name text DEFAULT 'generic',p_credits_to_use integer DEFAULT 1) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Legacy credit debit retired; use request-specific reservations'; END $$;
CREATE OR REPLACE FUNCTION public.check_and_increment_ai_usage(p_user_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Legacy credit debit retired; use request-specific reservations'; END $$;
REVOKE EXECUTE ON FUNCTION public.check_and_increment_ai_usage(uuid,text,integer) FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.check_and_increment_ai_usage(uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.fulfill_payment_credits(p_user_id uuid,p_environment text,p_payment_key text,p_price_id text,p_period_start timestamptz DEFAULT NULL,p_period_end timestamptz DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Legacy payment fulfillment retired; use verified invoice grants'; END $$;
REVOKE EXECUTE ON FUNCTION public.fulfill_payment_credits(uuid,text,text,text,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.validate_credit_reservation_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status NOT IN ('held','consumed','released') THEN RAISE EXCEPTION 'Invalid reservation state'; END IF; RETURN NEW; END $$;
CREATE TRIGGER credit_reservation_validation BEFORE INSERT OR UPDATE ON public.credit_reservations FOR EACH ROW EXECUTE FUNCTION public.validate_credit_reservation_update();